//! The cross-implementation contract: `vectors/wallet.v1.json`. Every binding (UniFFI, wasm)
//! must reproduce these values byte for byte.
//!
//! Some inputs carry over unchanged from the earlier Kotlin core and pin the primitives
//! independently of this code: keccak, JCS, base58, the `cow` key and its signatures, the EIP-712
//! Mail example and the text policy. Everything that depends on names, tags or the credential
//! format is regenerated by [regenerate]:
//! `DJRUST_WALLET_REGEN=1 cargo test -p djrust-wallet --test vectors regenerate -- --ignored`.

use djrust_wallet::credential::{self, Credential, Disclosure, Unsigned};
use djrust_wallet::key::{self, did};
use djrust_wallet::merkle::{disclosure, Scheme};
use djrust_wallet::{base58, chart, cid, claims, hex, invites, jcs, keccak, legacy, posts, revocation, schema, snapshot, snapshot_share, time, Reason};
use serde_json::{json, Map, Value};

const PATH: &str = concat!(env!("CARGO_MANIFEST_DIR"), "/vectors/wallet.v1.json");

fn vectors() -> Value {
    jcs::parse(&std::fs::read_to_string(PATH).expect("vectors file")).expect("vectors parse")
}

fn s<'a>(v: &'a Value, k: &str) -> &'a str {
    v[k].as_str().unwrap_or_else(|| panic!("{k} is not a string"))
}

fn kh(s: &str) -> [u8; 32] {
    keccak(s.as_bytes())
}

fn priv_for(v: &Value, seed: &str) -> Vec<u8> {
    let k = v["keys"].as_array().unwrap().iter().find(|k| s(k, "seedUtf8") == seed).unwrap();
    hex::decode(s(k, "priv")).unwrap()
}

fn did_of(seed: &str) -> String {
    did::pkh(&key::address(&kh(seed)).unwrap())
}

const NOW: u64 = 1_790_000_000;

/// The statement credentials: (name, schema, subject, key seed, validUntil). Built from fixed
/// inputs so they regenerate the same.
fn statements(v: &Value) -> Vec<(&'static str, &'static schema::SchemaDoc, Value, &'static str, u64)> {
    let inviter = did_of("bitwrap-vector-1");
    let member = did_of("bitwrap-vector-2");
    let code: [u8; 16] = kh("invite-code")[..16].try_into().unwrap();
    let invite = invites::data(&inviter, &code, None).unwrap();
    // the same inputs as the "invite" statement below, so the accept names that credential
    let invite_cred = sign_with(&schema::BITWRAP_INVITE_V1, &invite, "bitwrap-vector-1", 0, b"invite");
    let track = s(&v["snapshot"], "cid");
    vec![
        ("invite", &schema::BITWRAP_INVITE_V1, invite, "bitwrap-vector-1", 0),
        ("inviteAccept", &schema::BITWRAP_INVITE_ACCEPT_V1, invites::accept_data(&invite_cred.cid(), &inviter, &member).unwrap(), "bitwrap-vector-2", 0),
        ("revocation", &schema::BITWRAP_REVOCATION_V1, revocation::data(&member), "bitwrap-vector-2", 0),
        (
            "chartClaim",
            &schema::BITWRAP_CHART_CLAIM_V1,
            chart::data(track, &member, 3, &kh("identity-log-row-3"), "djrust@0.1.0", &kh("render")).unwrap(),
            "bitwrap-vector-2",
            0,
        ),
        ("snapshotShare", &schema::BITWRAP_SNAPSHOT_SHARE_V1, snapshot_share::data(&cid::of_json(&v["djSnapshot"]).unwrap()).unwrap(), "bitwrap-vector-1", 0),
        ("discoveryClaim", &schema::BEATS_DISCOVERY_CLAIM_V1, v["snapshot"]["claimData"].clone(), "bitwrap-vector-1", 0),
        ("post", &schema::BEATS_POST_V1, v["snapshot"]["postData"].clone(), "bitwrap-vector-1", NOW + 86_400),
    ]
}

fn salt_for(tag: &[u8]) -> Vec<u8> {
    keccak(tag).to_vec()
}

fn sign_with(sch: &schema::SchemaDoc, subject: &Value, seed: &str, until: u64, salt_tag: &[u8]) -> Credential {
    let sealed = credential::seal(sch.id(), subject, &did_of(seed), NOW, until, &salt_for(salt_tag)).unwrap();
    credential::sign(&sealed, &kh(seed)).unwrap()
}

/// Rewrites every derived value of the vectors file from this crate's code.
#[test]
#[ignore]
fn regenerate() {
    if std::env::var("DJRUST_WALLET_REGEN").as_deref() != Ok("1") {
        panic!("set DJRUST_WALLET_REGEN=1 to rewrite {PATH}");
    }
    let mut v = vectors();
    for k in v["keys"].as_array_mut().unwrap() {
        let p = kh(s(k, "seedUtf8"));
        k["priv"] = json!(hex::encode0x(&p));
        k["pub"] = json!(hex::encode0x(&key::public_key(&p).unwrap()));
        k["address"] = json!(key::address(&p).unwrap());
        k["did"] = json!(did::pkh(&key::address(&p).unwrap()));
    }
    let snapshot = v.clone();
    for c in v["signatures"].as_array_mut().unwrap() {
        let d = hex::decode_n::<32>(s(c, "digest")).unwrap();
        c["signature"] = json!(key::sign(&d, &priv_for(&snapshot, s(c, "key"))).unwrap().hex());
    }
    v["schemas"] = Value::Object(schema::all().iter().map(|d| (d.name.to_string(), json!(d.cid()))).collect());
    v["schemaIds"] = Value::Object(schema::all().iter().map(|d| (d.name.to_string(), json!(d.id()))).collect());
    for c in v["merkle"].as_array_mut().unwrap() {
        let sch = Scheme::new(s(c, "tag")).unwrap();
        let n = c["count"].as_u64().unwrap() as usize;
        let leaves: Vec<Vec<u8>> = (0..n).map(|i| format!("leaf-{i}").into_bytes()).collect();
        c["root"] = json!(hex::encode0x(&sch.root(&leaves)));
        c["proofs"] = Value::Array((0..n).map(|i| sch.prove(&leaves, i).unwrap().to_json()).collect());
    }
    {
        use djrust_wallet::anchor::batch_tree;
        for b in v["batches"].as_array_mut().unwrap() {
            let leaves: Vec<Vec<u8>> = b["leaves"].as_array().unwrap().iter().map(|l| hex::decode(l.as_str().unwrap()).unwrap()).collect();
            b["root"] = json!(hex::encode0x(&batch_tree::root(&leaves).unwrap()));
            b["proofs"] = Value::Array((0..leaves.len()).map(|i| batch_tree::prove(&leaves, i).unwrap().to_json()).collect());
        }
    }
    let did1 = s(&v["keys"][1], "did").to_string();
    v["snapshot"]["claimData"] = claims::data(s(&v["snapshot"], "cid"), &did1);
    {
        use djrust_wallet::anchor::{commitment, root_log};
        v["snapshot"]["commitment"] = json!(hex::encode0x(&commitment::of(&did1, "zClaim0", &kh("salt")).unwrap()));
        let r = &mut v["rootLog"];
        let d = root_log::digest_of(
            r["seq"].as_u64().unwrap(),
            r["time"].as_u64().unwrap(),
            &hex::decode_n::<32>(s(r, "prev")).unwrap(),
            &hex::decode_n::<32>(s(r, "root")).unwrap(),
        );
        r["digest"] = json!(hex::encode0x(&d));
        r["signature"] = json!(key::sign(&d, &kh("bitwrap-vector-1")).unwrap().hex());
    }
    {
        let l = &mut v["legacy"];
        let signed = legacy::sign(l["share"].as_object().unwrap(), &kh(s(l, "key"))).unwrap();
        l["recovered"] = json!(legacy::verify(&signed).unwrap());
        l["signed"] = Value::Object(signed);
    }
    let snapshot = v.clone();
    for e in v["credentials"].as_array_mut().unwrap() {
        let sch = schema::by_name(s(e, "schema")).unwrap();
        let salt = hex::decode(s(e, "docSalt")).unwrap();
        let p = priv_for(&snapshot, s(e, "key"));
        let issuer = did::pkh(&key::address(&p).unwrap());
        let sealed = credential::seal(sch.id(), &e["data"], &issuer, e["validFrom"].as_u64().unwrap(), e["validUntil"].as_u64().unwrap(), &salt).unwrap();
        let c = credential::sign(&sealed, &p).unwrap();
        let ptrs: Vec<String> = e["disclose"].as_array().unwrap().iter().map(|x| x.as_str().unwrap().to_string()).collect();
        let ptrs: Vec<&str> = ptrs.iter().map(String::as_str).collect();
        e["issuer"] = json!(issuer);
        e["leaves"] = Value::Array(disclosure::flatten(&e["data"]).into_iter().map(|l| json!(l.pointer)).collect());
        e["documentHash"] = json!(hex::encode0x(&sealed.unsigned.document_hash().unwrap()));
        e["digest"] = json!(hex::encode0x(&sealed.unsigned.digest().unwrap()));
        e["typedData"] = sealed.unsigned.typed_data_json().unwrap();
        e["credential"] = c.to_json();
        e["credentialCid"] = json!(c.cid());
        e["disclosure"] = Disclosure::of(&c, &sealed, &ptrs).unwrap().to_json();
    }
    let snapshot = v.clone();
    let mut st = Map::new();
    for (name, sch, subject, seed, until) in statements(&snapshot) {
        let c = sign_with(sch, &subject, seed, until, name.as_bytes());
        st.insert(name.into(), json!({"credential": c.to_json(), "credentialCid": c.cid(), "bytes": jcs::bytes(&c.to_json()).unwrap().len()}));
    }
    v["statements"] = Value::Object(st);
    v["time"] = Value::Array([0u64, 951_782_400, NOW, time::MAX].iter().map(|t| json!({"unix": t, "dateTime": time::format(*t).unwrap()})).collect());
    let host = "alice.bitwrap.io";
    v["did"] = json!({
        "pkh": did1,
        "pkhDocument": did::pkh_document(&did1).unwrap(),
        "webHost": host,
        "web": did::web(host).unwrap(),
        "webDocumentUrl": did::web_document_url(host).unwrap(),
        "webDocument": did::web_document(host, &did1).unwrap(),
    });
    std::fs::write(PATH, serde_json::to_string_pretty(&v).unwrap() + "\n").unwrap();
}

#[test]
fn keccak_vectors() {
    for c in vectors()["keccak"].as_array().unwrap() {
        assert_eq!(hex::encode0x(&kh(s(c, "utf8"))), s(c, "hash"));
    }
}

#[test]
fn jcs_and_cid_vectors() {
    let v = vectors();
    for c in v["jcs"].as_array().unwrap() {
        let input = s(c, "input");
        assert_eq!(jcs::canonicalize_str(input).unwrap(), s(c, "canonical"), "input {input}");
        assert_eq!(cid::of_json_str(input).unwrap(), s(c, "cid"));
    }
    for bad in v["jcsRejects"].as_array().unwrap() {
        assert!(jcs::canonicalize_str(bad.as_str().unwrap()).is_err(), "{bad}");
    }
    // Rust strings cannot hold a lone surrogate: rejected at parse.
    assert!(jcs::parse(r#"["\ud800"]"#).is_err());
}

#[test]
fn base58_vectors() {
    for c in vectors()["base58"].as_array().unwrap() {
        let raw = hex::decode(s(c, "hex")).unwrap();
        assert_eq!(base58::encode(&raw), s(c, "b58"));
        assert_eq!(base58::decode(s(c, "b58")).unwrap(), raw);
    }
}

#[test]
fn cid_shape() {
    let c = cid::of_json_str(r#"{"a":1}"#).unwrap();
    assert!(cid::is_valid(&c));
    assert!(!cid::is_valid("zabc"));
    assert!(!cid::is_valid(&format!("Qm{}", &c[1..])));
    assert!(cid::digest("z0OIl").is_none());
}

#[test]
fn key_vectors() {
    for k in vectors()["keys"].as_array().unwrap() {
        let p = hex::decode(s(k, "priv")).unwrap();
        assert_eq!(p, kh(s(k, "seedUtf8")));
        assert_eq!(hex::encode0x(&key::public_key(&p).unwrap()), s(k, "pub"));
        assert_eq!(key::address(&p).unwrap(), s(k, "address"));
        assert_eq!(did::pkh(s(k, "address")), s(k, "did"));
        let (chain, a) = did::parse(s(k, "did")).unwrap();
        assert_eq!(chain, 1);
        assert_eq!(key::checksum_address(&a), s(k, "address"));
    }
    // the cow key is Ethereum's well-known test key, from outside this crate
    assert_eq!(s(&vectors()["keys"][0], "address"), "0xCD2a3d9F938E13CD947Ec05AbC7FE734Df8DD826");
    assert!(did::parse("did:pkh:eip155:1:0x123").is_none());
    assert!(did::parse("did:pkh:eip155::0xCD2a3d9F938E13CD947Ec05AbC7FE734Df8DD826").is_none());
}

#[test]
fn signature_vectors_are_deterministic_low_s_and_recover() {
    let v = vectors();
    for c in v["signatures"].as_array().unwrap() {
        let p = priv_for(&v, s(c, "key"));
        let d = hex::decode_n::<32>(s(c, "digest")).unwrap();
        let sig = key::sign(&d, &p).unwrap();
        assert_eq!(sig.hex(), s(c, "signature"));
        assert!(key::is_low_s(&sig));
        let addr = key::recover_address(&d, &sig).unwrap();
        assert_eq!(key::checksum_address(&addr), key::address(&p).unwrap());
    }
    for c in v["personalSign"].as_array().unwrap() {
        assert_eq!(hex::encode0x(&key::personal_message_hash(s(c, "utf8").as_bytes())), s(c, "hash"));
    }
}

#[test]
fn high_s_recovers_but_is_flagged() {
    let p = kh("bitwrap-vector-1");
    let d = kh("m1");
    let sig = key::sign(&d, &p).unwrap();
    // s' = n - s, v flipped: the classic malleated twin
    let n = hex::decode("fffffffffffffffffffffffffffffffebaaedce6af48a03bbfd25e8cd0364141").unwrap();
    let mut s_hi = [0u8; 32];
    let mut borrow = 0i16;
    for i in (0..32).rev() {
        let x = n[i] as i16 - sig.0[32 + i] as i16 - borrow;
        borrow = (x < 0) as i16;
        s_hi[i] = (x + 256 * borrow) as u8;
    }
    let mut hi = sig;
    hi.0[32..64].copy_from_slice(&s_hi);
    hi.0[64] = if sig.0[64] == 27 { 28 } else { 27 };
    assert!(!key::is_low_s(&hi));
    assert_eq!(key::recover_address(&d, &hi), key::recover_address(&d, &sig));
}

#[test]
fn schema_cids_and_ids_are_pinned() {
    let v = vectors();
    let pinned = v["schemas"].as_object().unwrap();
    let ids = v["schemaIds"].as_object().unwrap();
    assert_eq!(pinned.len(), schema::all().len());
    for doc in schema::all() {
        assert_eq!(doc.cid(), pinned[doc.name].as_str().unwrap(), "{}", doc.name);
        assert_eq!(doc.id(), ids[doc.name].as_str().unwrap(), "{}", doc.name);
        assert!(doc.id().starts_with("https://") && doc.id().contains("bitwrap.io/schema/"), "{}", doc.id());
        assert!(doc.id().ends_with(&format!("/{}.schema.json", doc.name)), "{}", doc.id());
        assert_eq!(schema::by_cid(doc.cid()).unwrap().name, doc.name);
        assert_eq!(schema::by_id(doc.id()).unwrap().name, doc.name);
    }
}

#[test]
fn credential_vectors() {
    let v = vectors();
    for e in v["credentials"].as_array().unwrap() {
        let p = priv_for(&v, s(e, "key"));
        let sch = schema::by_name(s(e, "schema")).unwrap();
        let salt = hex::decode(s(e, "docSalt")).unwrap();
        let data = &e["data"];
        let leaves: Vec<String> = disclosure::flatten(data).into_iter().map(|l| l.pointer).collect();
        let want: Vec<&str> = e["leaves"].as_array().unwrap().iter().map(|x| x.as_str().unwrap()).collect();
        assert_eq!(leaves, want);

        let from = e["validFrom"].as_u64().unwrap();
        let sealed = credential::seal(sch.id(), data, s(e, "issuer"), from, e["validUntil"].as_u64().unwrap(), &salt).unwrap();
        assert_eq!(hex::encode0x(&sealed.unsigned.document_hash().unwrap()), s(e, "documentHash"));
        assert_eq!(hex::encode0x(&sealed.unsigned.digest().unwrap()), s(e, "digest"));
        assert_eq!(sealed.unsigned.typed_data_json().unwrap(), e["typedData"]);
        let c = credential::sign(&sealed, &p).unwrap();
        assert_eq!(c.to_json(), e["credential"]);
        assert_eq!(c.cid(), s(e, "credentialCid"));
        assert_eq!(Credential::from_json(&e["credential"]).unwrap(), c);

        // the external-signer path: unsigned JSON out, 65-byte signature back in
        let mut unsigned_json = e["credential"].clone();
        unsigned_json["proof"].as_object_mut().unwrap().remove("proofValue");
        let u = Unsigned::from_json(&unsigned_json).unwrap();
        assert_eq!(u.with_signature(c.signature), c);

        let ok = credential::verify(&c, from + 10, 300).unwrap();
        assert_eq!(ok.signer_did, s(e, "issuer"));
        credential::check_root(&c, &salt).unwrap();
        credential::check_schema(&c, Some(sch.json())).unwrap();

        let ptrs: Vec<&str> = e["disclose"].as_array().unwrap().iter().map(|x| x.as_str().unwrap()).collect();
        let d = Disclosure::of(&c, &sealed, &ptrs).unwrap();
        assert_eq!(d.to_json(), e["disclosure"]);
        let parsed = Disclosure::from_json(&e["disclosure"]).unwrap();
        assert_eq!(credential::verify_disclosure(&parsed, from + 10, 300).unwrap().signer_did, s(e, "issuer"));

        // a tampered disclosed value no longer proves
        let mut bad = parsed.clone();
        bad.fields[0].value = Value::String("house".into());
        assert_eq!(credential::verify_disclosure(&bad, from + 10, 300).unwrap_err().reason, Reason::ProofInvalid);
        // nor does a disclosure whose window was moved: created is in the signed proof config
        let mut moved = parsed.clone();
        moved.proof["created"] = json!(time::format(from - 1).unwrap());
        assert_eq!(credential::verify_disclosure(&moved, from + 10, 300).unwrap_err().reason, Reason::IssuerMismatch);
    }
}

#[test]
fn credentials_are_strict_and_tamper_evident() {
    let v = vectors();
    let e = &v["credentials"][0];
    let c = Credential::from_json(&e["credential"]).unwrap();
    let now = c.valid_from() + 10;
    // any change to the document moves the document hash, so the signature recovers another key
    for (ptr, val) in [("/credentialSubject/genre", json!("house")), ("/validFrom", json!("2026-01-01T00:00:00Z")), ("/issuer", json!(s(&v["keys"][2], "did")))] {
        let mut t = e["credential"].clone();
        *t.pointer_mut(ptr).unwrap() = val;
        // a changed issuer or validFrom no longer matches the proof's verificationMethod or
        // created, so the strict parse refuses it; anything else fails the signature
        match Credential::from_json(&t) {
            Err(_) => assert_ne!(ptr, "/credentialSubject/genre"),
            Ok(tc) => assert_eq!(credential::verify(&tc, now, 300).unwrap_err().reason, Reason::IssuerMismatch, "{ptr}"),
        }
    }
    // members this crate does not write are refused, not ignored
    let mut extra = e["credential"].clone();
    extra["id"] = json!("urn:uuid:1");
    assert!(Credential::from_json(&extra).is_err());
    let mut suite = e["credential"].clone();
    suite["proof"]["cryptosuite"] = json!("ecdsa-jcs-2019");
    assert!(Credential::from_json(&suite).is_err());
    // the window
    assert_eq!(credential::verify(&c, c.valid_from() - 301, 300).unwrap_err().reason, Reason::NotYetValid);
    let post = Credential::from_json(&v["statements"]["post"]["credential"]).unwrap();
    assert_eq!(credential::verify(&post, post.valid_until(), 300).unwrap_err().reason, Reason::Expired);
    // the key must be the issuer's
    let sealed = credential::seal(schema::BEATS_TRACK_V1.id(), &e["data"], s(&v["keys"][2], "did"), now, 0, &[1; 32]).unwrap();
    assert!(credential::sign(&sealed, &kh("bitwrap-vector-1")).is_err());
}

#[test]
fn credential_shape_follows_the_standards() {
    let v = vectors();
    let c = &v["statements"]["invite"]["credential"];
    assert_eq!(c["@context"], json!(["https://www.w3.org/ns/credentials/v2", "https://bitwrap.io/ns/credentials/v1"]));
    assert_eq!(c["type"], json!(["VerifiableCredential", "BitwrapCredential"]));
    assert_eq!(c["credentialSchema"], json!({"id": "https://bitwrap.io/schema/bitwrap-invite.v1.schema.json", "type": "JsonSchema"}));
    let p = &c["proof"];
    assert_eq!(p["type"], "DataIntegrityProof");
    assert_eq!(p["cryptosuite"], "bitwrap-eip712-jcs-2026");
    assert_eq!(p["proofPurpose"], "assertionMethod");
    assert_eq!(p["verificationMethod"], json!(format!("{}#blockchainAccountId", s(c, "issuer"))));
    assert!(s(p, "proofValue").starts_with('z'));
    assert_eq!(base58::decode(&s(p, "proofValue")[1..]).unwrap().len(), 65);
    assert_eq!(p["created"], c["validFrom"]);
    // the JSON-LD context names every term the credentials use
    let ctx: Value = jcs::parse(include_str!("../../../schema/bitwrap-credentials.v1.context.jsonld")).unwrap();
    let terms = ctx["@context"].as_object().unwrap();
    for (_, st) in v["statements"].as_object().unwrap() {
        let subj = &st["credential"]["credentialSubject"];
        let t = s(subj, "@type");
        assert!(terms.contains_key(t), "{t}");
        for k in subj.as_object().unwrap().keys().filter(|k| !k.starts_with('@') && *k != "id") {
            assert!(terms.contains_key(k.as_str()) || t == "DjSnapshot" || t == "BeatsShare", "{t}.{k}");
        }
    }
    assert!(terms.contains_key("disclosureRoot") && terms.contains_key("BitwrapCredential"));
}

#[test]
fn typed_data_json_is_what_an_external_wallet_signs() {
    use djrust_wallet::eip712::{Field, TypedData, Val};
    use std::collections::BTreeMap;
    let v = vectors();
    let e = &v["credentials"][0];
    let td = &e["typedData"];
    assert_eq!(td["domain"], json!({"name": "bitwrap.io", "version": "1", "chainId": 1}));
    assert_eq!(td["primaryType"], "DataIntegrity");
    // rebuild the digest from the JSON alone, as eth_signTypedData_v4 would
    let t = TypedData {
        types: BTreeMap::from([("DataIntegrity".into(), vec![Field::new("proofConfig", "bytes32"), Field::new("document", "bytes32")])]),
        primary_type: "DataIntegrity".into(),
        domain: BTreeMap::from([
            ("name".into(), Val::Str("bitwrap.io".into())),
            ("version".into(), Val::Str("1".into())),
            ("chainId".into(), Val::Uint(1)),
        ]),
        message: BTreeMap::from([
            ("proofConfig".into(), Val::Str(s(&td["message"], "proofConfig").into())),
            ("document".into(), Val::Str(s(&td["message"], "document").into())),
        ]),
    };
    assert_eq!(t.encode_type("DataIntegrity").unwrap(), "DataIntegrity(bytes32 proofConfig,bytes32 document)");
    assert_eq!(hex::encode0x(&t.signing_hash().unwrap()), s(e, "digest"));
    assert_eq!(s(&td["message"], "document"), s(e, "documentHash"));
    // proofConfig is ecdsa-jcs-2019's: sha256(JCS(proof minus proofValue, plus the document's @context))
    let mut pc = e["credential"]["proof"].clone();
    pc.as_object_mut().unwrap().remove("proofValue");
    pc["@context"] = e["credential"]["@context"].clone();
    use sha2::{Digest, Sha256};
    assert_eq!(hex::encode0x(&Sha256::digest(jcs::bytes(&pc).unwrap())), s(&td["message"], "proofConfig"));
    let mut doc = e["credential"].clone();
    doc.as_object_mut().unwrap().remove("proof");
    assert_eq!(hex::encode0x(&Sha256::digest(jcs::bytes(&doc).unwrap())), s(e, "documentHash"));
}

#[test]
fn statement_vectors() {
    let v = vectors();
    let st = &v["statements"];
    for (name, sch, subject, seed, until) in statements(&v) {
        let c = sign_with(sch, &subject, seed, until, name.as_bytes());
        assert_eq!(c.to_json(), st[name]["credential"], "{name}");
        assert_eq!(c.cid(), s(&st[name], "credentialCid"), "{name}");
    }
    let get = |n: &str| Credential::from_json(&st[n]["credential"]).unwrap();
    let now = NOW + 10;
    let member = did_of("bitwrap-vector-2");
    let (invite, accept) = (get("invite"), get("inviteAccept"));
    assert_eq!(invites::check(&invite, now, 300).unwrap().signer_did, did_of("bitwrap-vector-1"));
    assert_eq!(invites::check_accept(&accept, &invite, now, 300).unwrap().signer_did, member);
    assert_eq!(revocation::check(&get("revocation"), now, 300).unwrap().signer_did, member);
    let claim = chart::check(&get("chartClaim"), &v["snapshot"]["doc"], now, 300).unwrap();
    assert_eq!(claim.track, s(&v["snapshot"], "cid"));
    assert_eq!(claim.engine, "djrust@0.1.0");
    assert_eq!(claims::check(&get("discoveryClaim"), now, 300).unwrap().signer_did, did_of("bitwrap-vector-1"));
    posts::check(&get("post"), now, 300).unwrap();
    // a snapshot share names the (unsigned) DjSnapshot by its CID, checked with or without it
    let share = snapshot_share::check(&get("snapshotShare"), Some(&v["djSnapshot"]), now, 300).unwrap();
    assert_eq!(share.snapshot, cid::of_json(&v["djSnapshot"]).unwrap());
    assert_eq!(snapshot_share::check(&get("snapshotShare"), None, now, 300).unwrap().snapshot, share.snapshot);
    // every statement fits the storage service's 1,536-byte blob limit (docs/STANDARDS.md "Size")
    for (name, x) in st.as_object().unwrap() {
        assert!(x["bytes"].as_u64().unwrap() <= 1536, "{name}: {}", x["bytes"]);
    }
}

#[test]
fn statement_checks_refuse_the_wrong_thing() {
    let v = vectors();
    let st = &v["statements"];
    let get = |n: &str| Credential::from_json(&st[n]["credential"]).unwrap();
    let now = NOW + 10;
    // a statement under another schema
    assert_eq!(invites::check(&get("revocation"), now, 300).unwrap_err().reason, Reason::WrongSchema);
    // a revocation of someone else
    let rev = revocation::data(&did_of("bitwrap-vector-1"));
    let c = sign_with(&schema::BITWRAP_REVOCATION_V1, &rev, "bitwrap-vector-2", 0, b"x");
    assert_eq!(revocation::check(&c, now, 300).unwrap_err().reason, Reason::ClaimMismatch);
    // a revocation that expires
    let rev = revocation::data(&did_of("bitwrap-vector-2"));
    let c = sign_with(&schema::BITWRAP_REVOCATION_V1, &rev, "bitwrap-vector-2", NOW + 100, b"x");
    assert_eq!(revocation::check(&c, now, 300).unwrap_err().reason, Reason::BadWindow);
    // a chart claim for another track document
    let other = snapshot::of("house", 1, "loop").unwrap();
    assert_eq!(chart::check(&get("chartClaim"), &other, now, 300).unwrap_err().reason, Reason::SnapshotInvalid);
    // a chart claim credited to someone else
    let mut d = get("chartClaim").subject().clone();
    d["chartedBy"] = json!(did_of("bitwrap-vector-1"));
    let c = sign_with(&schema::BITWRAP_CHART_CLAIM_V1, &d, "bitwrap-vector-2", 0, b"x");
    assert_eq!(chart::check(&c, &v["snapshot"]["doc"], now, 300).unwrap_err().reason, Reason::ClaimMismatch);
    // a snapshot share checked against another document, or against something not a DjSnapshot
    let share = get("snapshotShare");
    let mut other = v["djSnapshot"].clone();
    other["mixer"]["crossfader"] = json!(0.25);
    assert_eq!(snapshot_share::check(&share, Some(&other), now, 300).unwrap_err().reason, Reason::SnapshotInvalid);
    assert_eq!(snapshot_share::check(&share, Some(&v["snapshot"]["doc"]), now, 300).unwrap_err().reason, Reason::SnapshotInvalid);
    assert_eq!(snapshot_share::check(&get("chartClaim"), None, now, 300).unwrap_err().reason, Reason::WrongSchema);
    assert!(snapshot_share::data("not-a-cid").is_err());
    // a snapshot is never itself signed: sealing one is refused, and so is a credential claiming
    // one of those schemas
    for sch in [&schema::DJ_SNAPSHOT_V1, &schema::BEATS_SNAPSHOT_V1] {
        assert!(credential::seal(sch.id(), &v["djSnapshot"], &did_of("bitwrap-vector-1"), NOW, 0, &[7; 32]).is_err(), "{}", sch.name);
    }
    let mut forged = st["snapshotShare"]["credential"].clone();
    forged["credentialSchema"]["id"] = json!(schema::DJ_SNAPSHOT_V1.id());
    if let Ok(c) = Credential::from_json(&forged) {
        assert_eq!(credential::check_schema(&c, None).err().map(|f| f.reason), Some(Reason::WrongSchema));
    }
    // an accept of a different invite
    let code: [u8; 16] = kh("another")[..16].try_into().unwrap();
    let inv2 = sign_with(&schema::BITWRAP_INVITE_V1, &invites::data(&did_of("bitwrap-vector-1"), &code, None).unwrap(), "bitwrap-vector-1", 0, b"y");
    assert_eq!(invites::check_accept(&get("inviteAccept"), &inv2, now, 300).unwrap_err().reason, Reason::ClaimMismatch);
}

#[test]
fn did_vectors() {
    let v = vectors();
    let d = &v["did"];
    let pkh = s(d, "pkh");
    assert_eq!(did::pkh_document(pkh).unwrap(), d["pkhDocument"]);
    assert_eq!(did::account_id(pkh).unwrap(), &pkh["did:pkh:".len()..]);
    let host = s(d, "webHost");
    assert_eq!(did::web(host).unwrap(), s(d, "web"));
    assert_eq!(did::web_document_url(host).unwrap(), s(d, "webDocumentUrl"));
    assert_eq!(did::web_document(host, pkh).unwrap(), d["webDocument"]);
    assert_eq!(did::check_web_document(host, &d["webDocument"]).as_deref(), Some(pkh));
    assert!(did::check_web_document("bob.bitwrap.io", &d["webDocument"]).is_none());
    for bad in ["", "localhost", "Alice.bitwrap.io", "alice.bitwrap.io:8443", "-a.bitwrap.io", "a..bitwrap.io", "a.bitwrap.io/x"] {
        assert!(did::web(bad).is_none(), "{bad}");
    }
    assert_eq!(d["pkhDocument"]["verificationMethod"][0]["type"], "EcdsaSecp256k1RecoveryMethod2020");
}

